def solve_game(N):
    # f[n] = 1 if n is a winning position, 0 if it's a losing position
    # A player who can move to N wins.
    f = [0] * (N + 1)
    # The player who writes N wins.
    # If a player is at n, and n+1=N or 2n=N, that player wins.
    # So f[n] = 1 if n+1=N or 2n=N.
    # In general, f[n] = 1 if there is a move to some m where f[m] = 0.
    # We should iterate backwards from N-1.
    for n in range(N - 1, 0, -1):
        # possible moves from n are n+1 and 2n
        can_move_to_L = False

        # Move to n+1
        if n + 1 == N:
            can_move_to_L = True
        elif n + 1 < N:
            if f[n+1] == 0:
                can_move_to_L = True

        # Move to 2n
        if not can_move_to_L:
            if 2 * n == N:
                can_move_to_L = True
            elif 2 * n < N:
                if f[2*n] == 0:
                    can_move_to_L = True

        if can_move_to_L:
            f[n] = 1
        else:
            f[n] = 0

    # A starts by writing 1.
    # Then it's B's turn to move from 1.
    # B wins if f[1] == 1.
    # A wins if f[1] == 0.
    return "B" if f[1] == 1 else "A"

for N in range(1, 15):
    print(f"N={N}: {solve_game(N)}")

